use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Gate;

class UploadController extends Controller
{
    use AuthorizesRequests;

    /** Each type with media fields, by Strapi uid: what an upload's `ref` may name. */
    private const TARGETS = [
        'api::post.post' => [\App\Models\Post::class, \App\Http\Serializers\PostSerializer::class],
        'api::book.book' => [\App\Models\Book::class, \App\Http\Serializers\BookSerializer::class],
    ];

    public function upload(Request $request): JsonResponse
    {
        if ($request->query('id') !== null) {
            return $this->updateInfo($request, (string) $request->query('id'));
        }
        $this->authorize('create', File::class);
        $uploads = $this->uploads($request);
        if ($uploads === []) {
            throw StrapiError::validation('Files are empty');
        }
        $infos = $this->infos($request);
        $entry = $this->entry($request);
        $stored = DB::transaction(function () use ($uploads, $infos, $entry): array {
            $stored = [];
            foreach ($uploads as $i => $upload) {
                $file = StrapiUpload::store($upload, $infos[$i] ?? []);
                if ($entry !== null) {
                    StrapiUpload::attach($entry['row'], $entry['relation'], $file);
                }
                $stored[] = $file;
            }

            return $stored;
        });

        return response()->json(array_map(fn (File $file) => StrapiUpload::wire($file), $stored), 201);
    }

    public function find(Request $request): JsonResponse
    {
        $this->authorize('viewAny', File::class);
        $params = $request->query();
        $query = $this->files($request);
        StrapiQuery::filter($query, $params, FileSerializer::FIELDS, $request->user(), null);
        StrapiQuery::order($query, $params['sort'] ?? null, FileSerializer::FIELDS, $request->user());

        return response()->json($query->get()->filter(fn (File $file) => Gate::allows('view', $file))
            ->map(fn (File $file) => StrapiQuery::select(StrapiUpload::wire($file), $params, FileSerializer::FIELDS))
            ->values()
            ->all());
    }

    /** Strapi's findOne reads only populate, so fields and filters do not narrow it. */
    public function findOne(Request $request, string $id): JsonResponse
